/*
 * ut_co_resume.cpp - 单元测试 for co_resume with nested calls
 */

#include "co_routine.h"
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// 全局计数器用于验证执行流程
static int g_exec_order = 0;
static int g_nested_complete = 0;

// 嵌套协程的入口函数
void* nested_co_entry(void* arg)
{
    printf("[Nested Co] Started, order=%d\n", ++g_exec_order);

    // 验证传入的参数
    int* value = (int*)arg;
    assert(*value == 42);

    printf("[Nested Co] Yielding, order=%d\n", ++g_exec_order);
    co_yield_ct();

    printf("[Nested Co] Resumed after yield, order=%d\n", ++g_exec_order);

    // 修改值表示嵌套协程完成
    *value = 100;
    g_nested_complete = 1;

    printf("[Nested Co] Completed, order=%d\n", ++g_exec_order);
    return NULL;
}

// 主协程入口函数 - 内部调用co_resume来启动嵌套协程
void* main_co_entry(void* arg)
{
    printf("[Main Co] Started, order=%d\n", ++g_exec_order);

    int nested_value = 42;
    stCoRoutine_t* nested_co = NULL;

    // 创建嵌套协程
    int ret = co_create(&nested_co, NULL, nested_co_entry, &nested_value);
    assert(ret == 0);
    assert(nested_co != NULL);

    printf("[Main Co] Created nested co, order=%d\n", ++g_exec_order);

    // 嵌套调用：在主协程中resume嵌套协程
    printf("[Main Co] About to resume nested co (first time), order=%d\n", ++g_exec_order);
    co_resume(nested_co);

    printf("[Main Co] Back from nested co (after yield), order=%d\n", ++g_exec_order);

    // 验证嵌套协程已经执行到yield点
    assert(g_exec_order >= 4);
    assert(nested_value == 42); // yield前没有修改值

    // 再次resume嵌套协程，让它完成
    printf("[Main Co] About to resume nested co (second time), order=%d\n", ++g_exec_order);
    co_resume(nested_co);

    printf("[Main Co] Back from nested co (completed), order=%d\n", ++g_exec_order);

    // 验证嵌套协程已完成
    assert(g_nested_complete == 1);
    assert(nested_value == 100);

    // 释放嵌套协程
    co_release(nested_co);

    printf("[Main Co] Completed, order=%d\n", ++g_exec_order);
    return NULL;
}

int main(int argc, char* argv[])
{
    printf("=== ut_co_resume: Testing co_resume with nested calls ===\n");

    stCoRoutine_t* main_co = NULL;

    // 创建主协程
    int ret = co_create(&main_co, NULL, main_co_entry, NULL);
    assert(ret == 0);
    assert(main_co != NULL);

    printf("[Main] Created main co\n");

    // 第一次resume主协程 - 这会启动主协程，主协程内部又会resume嵌套协程
    printf("[Main] Resuming main co (first time)\n");
    co_resume(main_co);

    printf("[Main] Back from main co (after nested yield)\n");

    // 第二次resume主协程
    printf("[Main] Resuming main co (second time)\n");
    co_resume(main_co);

    printf("[Main] Back from main co (nested completed)\n");

    // 第三次resume主协程 - 让它完成
    printf("[Main] Resuming main co (third time)\n");
    co_resume(main_co);

    printf("[Main] Main co completed\n");

    // 释放主协程
    co_release(main_co);

    printf("\n=== Test Result ===\n");
    printf("Total execution steps: %d\n", g_exec_order);
    printf("Nested completion flag: %d\n", g_nested_complete);

    if (g_nested_complete && g_exec_order >= 10) {
        printf("PASS: co_resume nested calls test passed!\n");
        return 0;
    } else {
        printf("FAIL: co_resume nested calls test failed!\n");
        return 1;
    }
}

