/*
 * ut_co_resume.cpp - 单元测试 for co_resume with nested calls
 *
 * 测试说明：
 * 这个测试验证了co_resume的嵌套调用功能。
 * libco的协程调用栈机制如下：
 * - 主线程有一个main协程在调用栈底
 * - 当co_resume(co)时，co被压入调用栈，控制权转移到co
 * - 当co_yield_ct()时，当前协程从调用栈弹出，控制权返回到栈中的前一个协程
 *
 * 嵌套调用场景：
 * 1. 主函数resume主协程(main_co)
 * 2. 主协程内部resume嵌套协程(nested_co)
 * 3. nested_co yield时返回到主线程（调用栈底），而非main_co
 * 4. 主线程再次resume main_co继续执行
 */

#include "co_routine.h"
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// 全局计数器用于验证执行流程
static int g_exec_order = 0;
static int g_nested_started = 0;
static int g_nested_after_yield = 0;
static int g_main_after_nested = 0;

// 嵌套协程的入口函数
void* nested_co_entry(void* arg)
{
    printf("[Nested Co] Started, order=%d\n", ++g_exec_order);
    g_nested_started = 1;

    // 验证传入的参数
    int* value = (int*)arg;
    assert(*value == 42);

    printf("[Nested Co] About to yield, order=%d\n", ++g_exec_order);

    // yield会返回到主线程（调用栈底）
    co_yield_ct();

    // 当主线程再次resume nested_co时会执行到这里
    printf("[Nested Co] Resumed after yield, order=%d\n", ++g_exec_order);
    g_nested_after_yield = 1;

    // 修改值表示嵌套协程完成
    *value = 100;

    printf("[Nested Co] Completed, order=%d\n", ++g_exec_order);
    return NULL;
}

// 主协程入口函数
void* main_co_entry(void* arg)
{
    printf("[Main Co] Started, order=%d\n", ++g_exec_order);

    stCoRoutine_t** nested_co_ptr = (stCoRoutine_t**)arg;
    int nested_value = 42;

    // 创建嵌套协程
    int ret = co_create(nested_co_ptr, NULL, nested_co_entry, &nested_value);
    assert(ret == 0);
    assert(*nested_co_ptr != NULL);

    printf("[Main Co] Created nested co, order=%d\n", ++g_exec_order);

    // 嵌套调用：在主协程中resume嵌套协程
    // 这会将nested_co压入调用栈，控制权转移到nested_co
    printf("[Main Co] About to resume nested co, order=%d\n", ++g_exec_order);
    co_resume(*nested_co_ptr);

    // 注意：当nested_co调用co_yield_ct()时，它直接返回到主线程，而不是这里！
    // 所以当主线程再次resume main_co时，会从这行代码之后继续执行

    printf("[Main Co] Back after nested_co yielded (resumed by main thread), order=%d\n", ++g_exec_order);
    g_main_after_nested = 1;

    // 再次resume nested_co让它完成
    printf("[Main Co] Resuming nested_co again to complete, order=%d\n", ++g_exec_order);
    co_resume(*nested_co_ptr);

    printf("[Main Co] Back after nested_co completed, order=%d\n", ++g_exec_order);

    // 验证嵌套协程已完成
    assert(g_nested_after_yield == 1);
    assert(nested_value == 100);

    // 释放嵌套协程
    co_release(*nested_co_ptr);
    *nested_co_ptr = NULL;

    printf("[Main Co] Completed, order=%d\n", ++g_exec_order);
    return NULL;
}

int main(int argc, char* argv[])
{
    printf("=== ut_co_resume: Testing co_resume with nested calls ===\n");
    printf("This test demonstrates how nested co_resume works in libco.\n\n");

    stCoRoutine_t* main_co = NULL;
    stCoRoutine_t* nested_co = NULL;

    // 创建主协程
    int ret = co_create(&main_co, NULL, main_co_entry, &nested_co);
    assert(ret == 0);
    assert(main_co != NULL);

    printf("[Main Thread] Created main co\n");

    // 第一次resume主协程
    // 这会将main_co压入调用栈，控制权转移到main_co
    printf("[Main Thread] Resuming main co (first time)\n");
    co_resume(main_co);

    // 此时，main_co已经执行，并调用了co_resume(nested_co)
    // nested_co开始执行，然后调用了co_yield_ct()
    // yield使nested_co从调用栈弹出，控制权返回到主线程（main协程）
    printf("[Main Thread] Back from main_co (nested_co yielded)\n");
    printf("[Main Thread] nested_co should be created and started\n");

    // 验证嵌套协程已经启动（执行到yield点）
    assert(g_nested_started == 1);
    assert(g_exec_order >= 4);

    // 现在nested_co在yield点等待，我们需要再次resume main_co让它继续
    printf("[Main Thread] Resuming main co (second time) to continue after nested yield\n");
    co_resume(main_co);

    printf("[Main Thread] Back from main_co\n");

    // 此时main_co应该已经再次resume了nested_co，nested_co完成执行
    // 控制权再次返回到主线程
    assert(g_main_after_nested == 1);

    // 第三次resume main_co让它完成
    printf("[Main Thread] Resuming main co (third time) to complete\n");
    co_resume(main_co);

    printf("[Main Thread] Main co completed\n");

    // 释放主协程
    co_release(main_co);
    main_co = NULL;

    printf("\n=== Test Result ===\n");
    printf("Total execution steps: %d\n", g_exec_order);
    printf("Nested started flag: %d\n", g_nested_started);
    printf("Nested after yield flag: %d\n", g_nested_after_yield);
    printf("Main after nested flag: %d\n", g_main_after_nested);

    if (g_nested_started && g_nested_after_yield && g_main_after_nested && g_exec_order >= 10) {
        printf("PASS: co_resume nested calls test passed!\n");
        return 0;
    } else {
        printf("FAIL: co_resume nested calls test failed!\n");
        return 1;
    }
}

