    // 这会将nested_co压入调用栈，控制权转移到nested_co
    printf("[Main Co] About to resume nested co, order=%d\n", ++g_exec_order);
    co_resume(*nested_co_ptr);

    // 注意：当nested_co调用co_yield_ct()时，它直接返回到主线程，而不是这里！
    // 所以当主线程再次resume main_co时，会从这行代码之后继续执行

    printf("[Main Co] Back after nested_co yielded (resumed by main thread), order=%d\n", ++g_exec_order);
    g_main_after_nested = 1;

    // 再次resume nested_co让它完成
